// Layout primitive (Category B) — arrangement only, owns no look.
// Carve-out 5 (component-contract.md §6): no Cmp token layer. Overlaps its items in one grid cell,
// each pinned to a side, a corner or the middle, so a badge sits over an image or copy over a
// banner and stays where it is pinned at every width: a design tool's absolute position with
// constraints, kept in flow. Later items paint over earlier ones, so source order is stacking order.
// An item is a `LayerItem`, the part that takes the pin; a bare child is not overlapped.
// Responsive: every layout prop accepts `T | { small, medium, large }` (block-contract.md § Responsive).
import type { CSSProperties, ElementType, HTMLAttributes, Ref } from "react";
import { responsiveVars, type Responsive } from "./responsive";
import "./Layer.css";

type Pin = "start" | "center" | "end" | "stretch";
type Inset = "none" | "2x-small" | "x-small" | "small" | "medium" | "large" | "x-large" | "2x-large";
const insetValue = (v: Inset) => (v === "none" ? "0" : `var(--sd-space-${v})`);

export interface LayerProps extends Omit<HTMLAttributes<HTMLElement>, "className"> {
  /**
   * At least the viewport's height, for a layer that is the page itself: a screen laid out freely,
   * as a design tool's frame is, has room to place into before anything is in it.
   *
   * @default false
   */
  isFullHeight?: boolean;
  /** Render as a different element (e.g. "section", "figure"). */
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export function Layer({ isFullHeight, as: Component = "div", className, ...props }: LayerProps) {
  return <Component {...props} data-full-height={isFullHeight || undefined} className={className ? `sd-layer ${className}` : "sd-layer"} />;
}

export interface LayerItemProps extends Omit<HTMLAttributes<HTMLElement>, "className"> {
  /**
   * Where the item sits on the block axis (top to bottom): pinned to the start, the middle, the
   * end, or stretched over the whole layer.
   *
   * @default "stretch"
   */
  align?: Responsive<Pin>;
  /**
   * Where the item sits on the inline axis (start to end), as `align` does on the block axis.
   *
   * @default "stretch"
   */
  justify?: Responsive<Pin>;
  /**
   * How far the item stands in from the layer's block edges (top and bottom), from the Sys space
   * scale: from the edge it is pinned to, or from both when stretched. A centred item stays centred.
   * With the pin, this is a design tool's constraint and its margin.
   *
   * @default "none"
   */
  insetBlock?: Responsive<Inset>;
  /**
   * How far the item stands in from the layer's inline edges (start and end), as `insetBlock` does.
   *
   * @default "none"
   */
  insetInline?: Responsive<Inset>;
  /** Render as a different element. */
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export function LayerItem({ align, justify, insetBlock, insetInline, as: Component = "div", className, style, ...props }: LayerItemProps) {
  return (
    <Component
      {...props}
      className={className ? `sd-layer__item ${className}` : "sd-layer__item"}
      style={{
        ...responsiveVars("item-align", align, (v) => v),
        ...responsiveVars("item-justify", justify, (v) => v),
        ...responsiveVars("item-inset-block", insetBlock, insetValue),
        ...responsiveVars("item-inset-inline", insetInline, insetValue),
        ...style,
      }}
    />
  );
}

/* Layer.css — .sd-layer
   Layout primitive: arrangement only, no Cmp layer (carve-out 5). Every item shares the one grid
   cell, so items overlap and the layer is as large as its largest item; each item's pin arrives as
   --sd-layout-item-* local intermediates, set inline, applied mobile-first. Not tokens. The layer
   isolates, so an item's own stacking stays inside it. */
.sd-layer {
  display: grid;
  grid-template: minmax(0, 1fr) / minmax(0, 1fr);
  isolation: isolate;
}

/* The page itself: at least the viewport's height, the dynamic unit so a phone's browser bar does
   not leave a gap. 100 of a viewport unit is the whole viewport, not a value on a scale. */
.sd-layer[data-full-height] {
  min-block-size: 100dvh;
}

.sd-layer__item {
  /* Block inheritance: a nested layer's item must not read an ancestor item's pin. */
  --sd-layout-item-align-small: initial;
  --sd-layout-item-align-medium: initial;
  --sd-layout-item-align-large: initial;
  --sd-layout-item-justify-small: initial;
  --sd-layout-item-justify-medium: initial;
  --sd-layout-item-justify-large: initial;
  --sd-layout-item-inset-block-small: initial;
  --sd-layout-item-inset-block-medium: initial;
  --sd-layout-item-inset-block-large: initial;
  --sd-layout-item-inset-inline-small: initial;
  --sd-layout-item-inset-inline-medium: initial;
  --sd-layout-item-inset-inline-large: initial;
  grid-area: 1 / 1;
  min-inline-size: 0;
  align-self: var(--sd-layout-item-align-small, stretch);
  justify-self: var(--sd-layout-item-justify-small, stretch);
  /* The inset is a margin on both sides: the pinned side's is the distance from that edge, the other
     side's only keeps a centred item centred and a stretched one inset on both. */
  margin-block: var(--sd-layout-item-inset-block-small, 0);
  margin-inline: var(--sd-layout-item-inset-inline-small, 0);
}

@media (min-width: 768px) {
  .sd-layer__item {
    align-self: var(--sd-layout-item-align-medium, var(--sd-layout-item-align-small, stretch));
    justify-self: var(--sd-layout-item-justify-medium, var(--sd-layout-item-justify-small, stretch));
    margin-block: var(--sd-layout-item-inset-block-medium, var(--sd-layout-item-inset-block-small, 0));
    margin-inline: var(--sd-layout-item-inset-inline-medium, var(--sd-layout-item-inset-inline-small, 0));
  }
}

@media (min-width: 1024px) {
  .sd-layer__item {
    align-self: var(
      --sd-layout-item-align-large,
      var(--sd-layout-item-align-medium, var(--sd-layout-item-align-small, stretch))
    );
    justify-self: var(
      --sd-layout-item-justify-large,
      var(--sd-layout-item-justify-medium, var(--sd-layout-item-justify-small, stretch))
    );
    margin-block: var(
      --sd-layout-item-inset-block-large,
      var(--sd-layout-item-inset-block-medium, var(--sd-layout-item-inset-block-small, 0))
    );
    margin-inline: var(
      --sd-layout-item-inset-inline-large,
      var(--sd-layout-item-inset-inline-medium, var(--sd-layout-item-inset-inline-small, 0))
    );
  }
}
